cat > docs/features/checkout-pricing/loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver and Gold (AC-1 to AC-4), values verbatim from the acceptance criteria.
  # NOT DECIDED, deliberately no scenario: Platinum tier. The business has not agreed a
  # reduction and no expected value exists. A scenario is added only once it does.
  # NOT DECIDED, deliberately no scenario: rounding for any subtotal other than AC-4's 7 cents.

  @happy-path @smoke
  Scenario: Bronze returning customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver returning customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold returning customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze returning customer with a very small basket is charged a whole cent amount
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_returning_customer_is_charged_the_Bronze_price()
    {
        // Bronze returning customer is charged the Bronze price
        var handler = new CalculateLoyaltyDiscount();

        var quote = handler.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
cat > src/CheckoutPricing.Application/CalculateLoyaltyDiscount.cs <<'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateLoyaltyDiscountQuery(int SubtotalCents, LoyaltyTier LoyaltyTier);

public sealed record LoyaltyDiscountQuote(
    int SubtotalCents,
    int DiscountCents,
    int TotalCents,
    LoyaltyTier LoyaltyTier);

public sealed class CalculateLoyaltyDiscount
{
    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query) =>
        new(query.SubtotalCents, 0, 0, query.LoyaltyTier);
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -20

